extension CodeBlockItemListSyntax: Swift.ExpressibleByStringLiteral, Swift.ExpressibleByExtendedGraphemeClusterLiteral, Swift.ExpressibleByUnicodeScalarLiteral {}
func typeOfShadowing() {
  // Try to shadow type(of:)
  func type<T>(of t: T.Type, flag: Bool) -> T.Type {
    return t
  }
  func type<T, U>(of t: T.Type, _ : U) -> T.Type {
    return t
  }
  func type<T>(_ t: T.Type) -> T.Type {
    return t
  }
  func type<T>(while t: T.Type) -> T.Type {
    return t
  }
  _ = type(of: Gen<Foo>.Bar)
  _ = type(Gen<Foo>.Bar)
  _ = type(of: Gen<Foo>.Bar.self, flag: false) // No error here.
  _ = type(fo: Foo
.Bar.self) // No error here.
  _ = type(of: Foo.Bar. self, [1, 2, 3]) // No error here.
}
}

